 applets/devicenotifier/devicecontrol.h    |  3 +
 applets/devicenotifier/qml/DeviceItem.qml |  7 +++
 applets/devicenotifier/stateinfo.cpp      | 74 +++++++++++++++++++++++
 applets/devicenotifier/stateinfo.h        | 23 +++++++
 5 files changed, 130 insertions(+), 1 deletion(-)

