+++ b/applets/devicenotifier/devicecontrol.cpp
@@ -122,6 +122,14 @@ QVariant DeviceControl::data(const QModelIndex &index, int role) const
     case Actions: {
         return deviceInfo.actionsInfo ? QVariant::fromValue(deviceInfo.actionsInfo.get()) : QVariant();
     }
+    case PendingWriteText: {
+        const qint64 bytes = deviceInfo.stateInfo ? deviceInfo.stateInfo->pendingWriteBytes() : -1;
+        return bytes > 0 ? KFormat().formatByteSize(bytes) : QString();
+    }
+    case PendingWriteTimeText: {
+        const qint64 seconds = deviceInfo.stateInfo ? deviceInfo.stateInfo->pendingWriteSeconds() : -1;
+        return seconds > 0 ? KFormat().formatSpelloutDuration(seconds * 1000) : QString();
+    }
     }

     return {};
@@ -147,6 +155,8 @@ QHash<int, QByteArray> DeviceControl::roleNames() const
     roles[Timestamp] = "deviceTimestamp";
     roles[Message] = "deviceMessage";
     roles[Actions] = "deviceActions";
+    roles[PendingWriteText] = "devicePendingWriteText";
+    roles[PendingWriteTimeText] = "devicePendingWriteTimeText";
     return roles;
 }

@@ -213,6 +223,7 @@ void DeviceControl::onDeviceAdded(const QString &udi)
     endInsertRows();

     connect(stateInfo.get(), &StateInfo::stateChanged, this, &DeviceControl::onDeviceStatusChanged);
+    connect(stateInfo.get(), &StateInfo::pendingWriteChanged, this, &DeviceControl::onDevicePendingWriteChanged);
     connect(spaceInfo.get(), &SpaceInfo::sizeChanged, this, &DeviceControl::onDeviceSizeChanged);
     connect(messageInfo.get(), &MessageInfo::messageChanged, this, &DeviceControl::onDeviceMessageChanged);

@@ -389,7 +400,7 @@ void DeviceControl::onDeviceStatusChanged(const QString &udi)
     for (int position = 0; position < m_devices.size(); ++position) {
         if (m_devices[position].storageInfo && m_devices[position].storageInfo->device().udi() == udi) {
             QModelIndex index = DeviceControl::index(position);
-            Q_EMIT dataChanged(index, index, {Mounted, State, OperationResult, Emblems, IsBusy});
+            Q_EMIT dataChanged(index, index, {Mounted, State, OperationResult, Emblems, IsBusy, PendingWriteText, PendingWriteTimeText});

             // If a deferred removal is pending and the device is no longer busy,
             // process the removal now.
@@ -415,4 +426,15 @@ void DeviceControl::onDeviceMessageChanged(const QString &udi)
     qCDebug(APPLETS::DEVICENOTIFIER) << "Device Controller: Error for device : " << udi << " Fail to update. Device not exists";
 }

+void DeviceControl::onDevicePendingWriteChanged(const QString &udi)
+{
+    for (int position = 0; position < m_devices.size(); ++position) {
+        if (m_devices[position].storageInfo && m_devices[position].storageInfo->device().udi() == udi) {
+            QModelIndex index = DeviceControl::index(position);
+            Q_EMIT dataChanged(index, index, {PendingWriteText, PendingWriteTimeText});
+            return;
+        }
+    }
+}
