@@ -110,6 +112,11 @@ PlasmaExtras.ExpandableListItem {
             return i18nc("Removing is a less technical word for Unmounting; translation should be short and mean \'Currently unmounting this device\'", "Removing…");
         } else if (deviceItem.deviceState === StateInfo.Unmounting) {
             // Unmounting; shown if unmount takes longer than 1 second
+            if (deviceItem.devicePendingWriteText !== "" && deviceItem.devicePendingWriteTimeText !== "") {
+                return i18nc("@info:status %1 is an amount of data, %2 is a duration", "Don't unplug yet! %1 still being transferred, about %2 left…", deviceItem.devicePendingWriteText, deviceItem.devicePendingWriteTimeText);
+            } else if (deviceItem.devicePendingWriteText !== "") {
+                return i18nc("@info:status %1 is an amount of data", "Don't unplug yet! %1 still being transferred…", deviceItem.devicePendingWriteText);
