diff --git a/applets/devicenotifier/stateinfo.cpp b/applets/devicenotifier/stateinfo.cpp
index a3e3060573..00df8e8951 100644
--- a/applets/devicenotifier/stateinfo.cpp
+++ b/applets/devicenotifier/stateinfo.cpp
@@ -8,6 +8,9 @@

 #include "devicenotifier_debug.h"

+#include <cmath>
+
+#include <QFile>
 #include <QTimer>

 #include <Solid/Camera>
@@ -21,6 +24,26 @@
 #include <Solid/StorageDrive>
 #include <Solid/StorageVolume>

+using namespace std::chrono_literals;
+
+// Data in the page cache that the kernel still has to write out, in bytes
+static qint64 readPendingWriteBytes()
+{
+    QFile file(QStringLiteral("/proc/meminfo"));
+    if (!file.open(QIODevice::ReadOnly | QIODevice::Text)) {
+        return -1;
+    }
+    qint64 kiloBytes = 0;
+    int found = 0;
+    for (const QByteArray &line : file.readAll().split('\n')) {
+        if (line.startsWith("Dirty:") || line.startsWith("Writeback:")) {
+            kiloBytes += line.mid(line.indexOf(':') + 1).trimmed().split(' ').value(0).toLongLong();
+            ++found;
+        }
+    }
+    return found == 2 ? kiloBytes * 1024 : -1;
+}
+
 StateInfo::StateInfo(const std::shared_ptr<StorageInfo> &storageInfo, QObject *parent)
     : QObject(parent)
     , m_isBusy(false)
@@ -32,6 +55,9 @@ StateInfo::StateInfo(const std::shared_ptr<StorageInfo> &storageInfo, QObject *p
     , m_deviceTimeStamp(QDateTime::currentDateTimeUtc())
     , m_storageInfo(storageInfo)
 {
+    m_pendingWriteTimer.setInterval(1s);
+    connect(&m_pendingWriteTimer, &QTimer::timeout, this, &StateInfo::updatePendingWrite);
+
     const Solid::Device &device = m_storageInfo->device();

     if (device.is<Solid::OpticalDisc>()) {
@@ -144,6 +170,48 @@ QVariant StateInfo::getOperationInfo() const
     return m_operationInfo;
 }

+qint64 StateInfo::pendingWriteBytes() const
+{
+    return m_pendingWriteBytes;
+}
+
+qint64 StateInfo::pendingWriteSeconds() const
+{
+    return m_pendingWriteSeconds;
+}
+
+void StateInfo::updatePendingWrite()
+{
+    const qint64 pending = readPendingWriteBytes();
+    if (pending > m_pendingWriteBaseline) {
+        m_pendingWriteBaseline = pending;
+        m_pendingWriteClock.start();
+    }
+
+    // Small amounts are mostly other devices' periodic writeback, not worth showing
+    const qint64 bytes = pending >= 1024 * 1024 ? pending : -1;
+    qint64 seconds = -1;
+    const qint64 elapsed = m_pendingWriteClock.elapsed();
+    if (bytes > 0 && elapsed >= 2000 && pending < m_pendingWriteBaseline) {
+        const double bytesPerSecond = (m_pendingWriteBaseline - pending) * 1000.0 / elapsed;
+        seconds = std::ceil(pending / bytesPerSecond);
+    }
+
+    if (bytes != m_pendingWriteBytes || seconds != m_pendingWriteSeconds) {
+        m_pendingWriteBytes = bytes;
+        m_pendingWriteSeconds = seconds;
+        Q_EMIT pendingWriteChanged(m_storageInfo->device().udi());
+    }
+}
+
+void StateInfo::stopPendingWrite()
+{
+    m_pendingWriteTimer.stop();
+    m_pendingWriteBaseline = -1;
+    m_pendingWriteBytes = -1;
+    m_pendingWriteSeconds = -1;
+}
+
 void StateInfo::setMountingState(const QString &udi)
 {
     qCDebug(APPLETS::DEVICENOTIFIER) << "State Info " << udi << " : state changed to Mounting";
@@ -161,6 +229,10 @@ void StateInfo::setUnmountingState(const QString &udi)
     m_isBusy = true;
     m_state = Unmounting;

+    stopPendingWrite();
+    m_pendingWriteTimer.start();
+    updatePendingWrite();
+
     Q_EMIT stateChanged(udi);
 }

@@ -201,6 +273,7 @@ void StateInfo::setNotPresentState(const QString &udi)
     // So there is no need to update it if the state is UnmountDone or Unmounting.
     if (m_state != UnmountDone && m_state != Unmounting && m_storageInfo->device().udi() == udi) {
         qCDebug(APPLETS::DEVICENOTIFIER) << "State Info " << udi << " : state changed to NotPresent";
+        stopPendingWrite();
         m_isBusy = false;
         m_isMounted = false;
         m_state = NotPresent;
@@ -212,6 +285,7 @@ void StateInfo::setNotPresentState(const QString &udi)

 void StateInfo::setIdleState(Solid::ErrorType operationResult, QVariant operationInfo, const QString &udi)
 {
+    stopPendingWrite();
     m_isBusy = false;
     m_operationResult = operationResult;
     m_operationInfo = operationInfo;
